#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("USAGE\n");
        return 1;
    }
    char *pattern = argv[1];
    char *string = argv[2];
    int pattern_len = strlen(pattern);
    int string_len = strlen(string);
    int match = 0;
    for (int i = 0; i < string_len; i++) {
        if (pattern[0] == '*' && pattern_len == 1) {
            match = 1;
            break;
        }
        if (pattern[0] == string[i]) {
            if (pattern_len == 1) {
                match = 1;
                break;
            }
            int j = 1;
            for (int k = i + 1; k < string_len; k++) {
                if (pattern[j] == string[k]) {
                    j++;
                    if (j == pattern_len) {
                        match = 1;
                        break;
                    }
                }
            }
        }
    }
    if (match) {
        printf("MATCH\n");
    } else {
        printf("NO_MATCH\n");
    }
    return 0;
}
